#!/usr/bin/env bash
# Checks the integration bench of compose.yaml once it is up: both agents are
# connected, the configuration generated by centreon-web reached the poller,
# and the central sees the poller's engine running.
set -euo pipefail

COMPOSE=(docker compose -f "$(dirname "$0")/compose.yaml")
failures=0

check() {
  local label=$1
  shift
  if "$@" > /dev/null 2>&1; then
    echo "ok    ${label}"
  else
    echo "FAIL  ${label}"
    failures=$((failures + 1))
  fi
}

nodes_connected() {
  "${COMPOSE[@]}" exec -T web curl -s localhost:8085/v1/nodes \
    | python3 -I -c 'import json,sys; n=json.load(sys.stdin)["nodes"]; sys.exit(0 if len(n) >= 2 and all(x["connected"] for x in n) else 1)'
}

poller_running() {
  "${COMPOSE[@]}" exec -T web mysql -hdb -uroot -pcentreon centreon_storage -N \
    -e "SELECT running FROM instances WHERE name = 'poller'" | grep -qx 1
}

check "Perl gorgoned is not running on the central" \
  bash -c "! ${COMPOSE[*]} exec -T web pgrep -f 'gorgoned( |$)'"
check "central and poller agents are connected to gorgone-server" nodes_connected
check "engine configuration was applied on the poller" \
  "${COMPOSE[@]}" exec -T poller test -s /etc/centreon-engine/.gorgone-engine.digest
check "broker configuration was applied on the poller" \
  "${COMPOSE[@]}" exec -T poller test -s /etc/centreon-broker/.gorgone-broker.digest
check "the central sees the poller's engine running" poller_running

echo
echo "Jobs handled by gorgone-server:"
"${COMPOSE[@]}" exec -T web python3 -c '
import sqlite3
db = sqlite3.connect("file:/var/lib/centreon-gorgone/gorgone-rs.db?mode=ro", uri=True)
for node, kind, state in db.execute("SELECT node_id, kind, state FROM jobs ORDER BY created_at"):
    print(f"  node {node:>20}  {kind:<16} {state}")
'

exit "${failures}"
